import numpy as np
import matplotlib.pyplot as plt
from scipy.io import wavfile
import os

# --- Configuration ---
# Define the paths to the three WAV files you want to compare.
# These are the files generated by TEST_SIMPLE_FIXES.py
# You can change these to point to any other result files.
# For example, from 'phase_2_new/results/exp_4d_combined/audio/'
AUDIO_FILES = {
    "Original Noise": "SIMPLE_FIX_err.wav",
    "Baseline (Failed)": "SIMPLE_FIX_baseline.wav",
    "Fixed (Scaled & Filtered)": "SIMPLE_FIX_optimized_scale_filter.wav"
}

# Output image file
OUTPUT_IMAGE = "anc_time_domain_comparison.png"

# --- Main Script ---

def plot_waveforms(audio_files, output_path):
    """
    Reads multiple WAV files, plots their time-domain signals in subplots,
    and saves the figure as an image.
    """
    num_files = len(audio_files)
    fig, axes = plt.subplots(num_files, 1, figsize=(15, 4 * num_files), sharex=True, sharey=True)
    
    if num_files == 1:
        axes = [axes] # Make it iterable if only one file

    print("Generating plot...")

    signals = {}
    fs = None

    # Read all files first to check for existence and get sample rate
    for i, (label, path) in enumerate(audio_files.items()):
        if not os.path.exists(path):
            print(f"ERROR: File not found at '{path}'.")
            # Check for the other possible filename from TEST_SIMPLE_FIXES.py
            alt_path = "SIMPLE_FIX_optimized_scale.wav"
            if "Fixed" in label and os.path.exists(alt_path):
                print(f"Found alternative '{alt_path}'. Using it instead.")
                path = alt_path
                audio_files[label] = alt_path # update path
            else:
                print("Please run 'TEST_SIMPLE_FIXES.py' first to generate the audio files.")
                return

        sample_rate, data = wavfile.read(path)
        
        if fs is None:
            fs = sample_rate
        elif fs != sample_rate:
            print(f"ERROR: Mismatched sample rates! Expected {fs} Hz, but found {sample_rate} Hz in '{path}'.")
            return

        # Convert to float [-1, 1]
        if data.dtype == np.int16:
            data = data.astype(np.float32) / 32767.0
        
        signals[label] = data

    # Find a representative slice to plot (e.g., 500ms) to see details
    plot_duration_ms = 500
    plot_samples = int(fs * (plot_duration_ms / 1000))
    
    # Find a region with high energy in the original noise to make the plot interesting
    err_signal = signals.get("Original Noise")
    if err_signal is not None and len(err_signal) > plot_samples:
        # Calculate energy in sliding windows
        window_size = plot_samples
        energies = np.array([np.mean(err_signal[i:i+window_size]**2) for i in range(len(err_signal) - window_size)])
        start_index = np.argmax(energies) if len(energies) > 0 else 0
    else:
        start_index = 0 # Default to start if original noise is not provided
        
    end_index = start_index + plot_samples

    # Plot each signal
    for i, (label, data) in enumerate(signals.items()):
        ax = axes[i]
        
        # Create time axis for the slice
        time_axis = np.arange(start_index, end_index) / fs
        signal_slice = data[start_index:end_index]

        ax.plot(time_axis, signal_slice, lw=1)
        ax.set_title(label, loc='left', fontsize=12)
        ax.grid(True, linestyle='--', alpha=0.6)
        ax.set_ylabel("Amplitude")
        ax.set_ylim([-1.0, 1.0]) # Set consistent y-axis limits

    # Final touches
    axes[-1].set_xlabel("Time (s)")
    fig.suptitle("ANC Performance: Time-Domain Waveform Comparison", fontsize=16, y=0.95)
    plt.tight_layout(rect=[0, 0, 1, 0.93]) # Adjust for suptitle

    # Save the plot
    plt.savefig(output_path, dpi=300)
    print(f"✓ Plot saved to '{output_path}'")


if __name__ == "__main__":
    # Check if matplotlib is installed
    try:
        import matplotlib.pyplot
    except ImportError:
        print("ERROR: matplotlib is not installed.")
        print("Please install it by running: pip install matplotlib")
    else:
        plot_waveforms(AUDIO_FILES, OUTPUT_IMAGE)